{"cmd":"cat > /root/local.rules <<'EOF'
# Custom exfil pattern for telemetry POSTs
alert http any any -> any any (
  msg:"TLM exfil telemetry report";
  flow:established,to_server;

  http.method;
  content:"POST";

  http.uri;
  pcre:"/^\\/telemetry\\/v2\\/report$/";

  http.header;
  content:"X-TLM-Mode|3a| exfil";
  nocase;

  http_client_body;
  content:"blob=";
  http_client_body;
  pcre:"/blob=[A-Za-z0-9+\\/]{80,}={0,2}(?:&|\\r?\\n|$)/";

  http_client_body;
  content:"sig=";
  http_client_body;
  pcre:"/sig=[0-9A-Fa-f]{64}(?:&|\\r?\\n|$)/";

  sid:1000001;
  rev:1;
)
EOF"}
